// ============================================================
// Portero de las reseñas: valida y frena el abuso ANTES de tocar
// la planilla. Publico == hostil hasta probar lo contrario.
// Las reseñas NUNCA se publican solas: quedan en la planilla para
// que alguien las revise y las copie a mano al codigo del blog.
// ============================================================

const TOPE_DIARIO = 50;   // reseñas por dia en total
const LARGO_MIN = 10;
const LARGO_MAX = 500;
const LIBROS_VALIDOS = ['padre', 'babilonia', 'pensar', 'lynch', 'triunfo', 'freak', 'vendes'];
const ORIGENES = [
  'https://obolfinance.com.ar',
  'https://obolfinance.github.io'
];

const entrada = $('Recibe la reseña').item.json;
const crudo = entrada.body ?? entrada;
let d;
try {
  d = typeof crudo === 'string' ? JSON.parse(crudo) : crudo;
} catch (e) {
  d = {};
}

function rechazar(motivo) {
  return [{ json: { ok: false, motivo } }];
}

// 0. Turnstile: Cloudflare ya confirmo (o no) que esto lo mando un humano.
const turnstileOk = $('Verifica Turnstile').item.json.success === true;
if (!turnstileOk) return rechazar('bot');

// 1. Origen. No es seguridad real (se falsifica facil), pero filtra el ruido.
const headers = entrada.headers || {};
const origen = headers.origin || headers.referer || '';
if (ORIGENES.length && !ORIGENES.some(o => origen.startsWith(o))) {
  return rechazar('origen');
}

// 2. Tope diario global.
const estado = $getWorkflowStaticData('global');
const hoy = new Date().toISOString().slice(0, 10);
if (estado.dia !== hoy) { estado.dia = hoy; estado.cuenta = 0; }
if (estado.cuenta >= TOPE_DIARIO) return rechazar('limite');

// 3. Contenido
const libro = String(d.libro || '').trim();
const nombre = String(d.nombre || '').trim().slice(0, 60);
const texto = String(d.texto || '').trim().slice(0, LARGO_MAX);
const estrellas = Number(d.estrellas);

const libroOk = LIBROS_VALIDOS.includes(libro);
const nombreOk = nombre.length > 0;
const textoOk = texto.length >= LARGO_MIN;
const estrellasOk = Number.isInteger(estrellas) && estrellas >= 1 && estrellas <= 5;

const ok = libroOk && nombreOk && textoOk && estrellasOk;
let motivo = '';
if (!ok) {
  motivo = !libroOk ? 'libro_invalido' : !nombreOk ? 'falta_nombre' : !textoOk ? 'texto_corto' : 'estrellas_invalidas';
}
if (ok) estado.cuenta = (estado.cuenta || 0) + 1;

return [{
  json: {
    ok,
    motivo,
    libro,
    nombre,
    estrellas,
    texto,
    pagina: d.pagina || '',
    fecha: new Date().toISOString(),
    publicada: 'NO'
  }
}];
